function saves(){const s=store.get(),bs=store.backups();modal('存檔與備份',`${recovery?'<p>尚未恢復紀錄。請匯入你已下載的有效備份。</p>':`<p>最後儲存：${new Date(s.savedAt).toLocaleString('zh-TW')}<br>本機：${store.saveHealth().local?'正常':'未寫入'}／獨立備援：${store.saveHealth().mirror?'正常':'不可用'}<br>${number(s.coins)} 金幣 · ${ROLE_MAP[s.role].name} · 收藏 ${Object.keys(s.owned).length} 種</p>`}<div class="actions">${button('下載完整備份','export',recovery?'disabled':'','primary')}${button('匯入備份','import')}</div><input id="import-file" type="file" accept=".json,application/json" hidden><h3>最近五份有效紀錄</h3>${bs.length?bs.map((b,i)=>`<div class="backup-row"><div>${new Date(b.state.savedAt).toLocaleString('zh-TW')}<small>${b.state.coins} 金幣 · ${ROLE_MAP[b.state.role].name}${b.state.pending?' · 有待結算旋轉':''}</small></div>${button('還原','restore',`data-index="${i}"`)}</div>`).join(''):'<p>操作後會自動產生輪替備份。</p>'}<p class="fine">瀏覽器與 IndexedDB 各保留一份存檔；清除網站資料可能一起刪除。下載到裝置的備份才能獨立保留。</p>${store.damagedCopies().length?button('下載受損紀錄','export-damaged'):''}`);$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2e6){toast('備份檔案過大，請使用本遊戲匯出的 JSON。');return}try{const raw=await file.text(),next=store.unpack(raw);confirmRestore(raw,next)}catch(err){toast('無法匯入：'+err.message)}};}
function confirmRestore(raw,s){const furn=Object.keys(s.owned).filter(id=>BY_ID[id].kind==='furniture').length,clothes=Object.keys(s.owned).filter(id=>BY_ID[id].kind!=='furniture').length;confirmAction('確認還原備份',`備份時間：${new Date(s.savedAt).toLocaleString('zh-TW')}<br>金幣：${number(s.coins)} · 家具 ${furn} 種 · 角色套裝 ${clothes} 種<br>目前紀錄會先加入輪替備份，再套用這份紀錄。`,'備份目前紀錄並還原',async()=>{await store.restore(raw);recovery=false;draft=null;selected=null;lastResult=null;lastGrid=null;page=store.get().started?'town':'welcome';if(store.get().pending)await animatePending();else render();toast('已還原備份。')})}
