async function enterTown(){const s=store.get();if(s.settings.reduced)return;const key=s.outfits[s.role].suit==='original'?s.role:s.outfits[s.role].suit,veil=document.createElement('div');veil.className='entry-transition';veil.innerHTML='<div class="entry-traveler"><img src="art/walk-'+key+'-a.webp" alt="走進小鎮"></div><b>'+ROLE_MAP[s.role].name+'的小日子，開始了。</b>';document.body.append(veil);const img=veil.querySelector('img');let i=0;const timer=setInterval(()=>{img.src='art/walk-'+key+'-'+(['a','c','b','d'][++i%4])+'.webp';sounds.play('step',{gain:.3});},130);await new Promise(r=>setTimeout(r,650));clearInterval(timer);veil.remove();}
