document.addEventListener('visibilitychange',()=>{if(document.hidden){audio?.suspend();skipPresentation();}else store.sync().then(()=>pumpAuto());});

async function styleProduct(kind,id){const s=store.get(),item=styleItem(kind,id);if(!item)throw Error('找不到房間收藏');const room=structuredClone(s.rooms[s.role]);room[kind==='theme'?'theme':'window']=id;const owned=kind==='theme'?s.themes.includes(id):s.windows.includes(id);modal(item.name,`<div class="style-preview"><canvas id="style-canvas" width="1400" height="560" aria-label="自己的家具與角色搭配預覽"></canvas><div><p>預覽 ${ROLE_MAP[s.role].name}目前的小屋；家具位置保留，購買一次全角色共用。</p><h3>${number(item.price)} 金幣</h3><p>${owned?'已收藏，可免費切換。':'目前 '+number(s.coins)+' 金幣。'}</p>${button(owned?'套用到我的小屋':'購買並套用','buy-style',`data-kind="${kind}" data-item="${id}" ${!owned&&s.coins<item.price?'disabled':''}`,'primary')}</div></div>`);void drawRoom($('#style-canvas'),room)}
async function previewSeries(id){const series=SERIES.find(t=>t.id===id),s=store.get(),list=FURNITURE.filter(i=>i.theme===id),room={...structuredClone(s.rooms[s.role]),theme:THEMES.some(t=>t.id===id)?id:s.rooms[s.role].theme,items:[]};for(const i of list){const spot=emptySpot(room,i.id);if(spot)room.items.push(spot)}const missing=list.filter(i=>!s.owned[i.id]),price=missing.reduce((n,i)=>n+i.price,0);modal(series.name+'・整套搭配',`<div class="style-preview"><canvas id="series-canvas" width="1400" height="560" aria-label="系列家具搭配預覽"></canvas><div><p>已收藏 ${list.length-missing.length}／${list.length} 件。預覽不修改你的布置。</p><p>房間背景另外購買。只購買尚未擁有的家具，不重複扣款。</p><h3>${number(price)} 金幣</h3>${button(missing.length?'收藏剩餘 '+missing.length+' 件':'系列已完整收藏','buy-series',`data-series="${id}" ${!missing.length||s.coins<price?'disabled':''}`,'primary')}</div></div>`);void drawRoom($('#series-canvas'),room)}
function layoutDialog(){const s=store.get(),plans=s.layouts[s.role];modal('小屋布置方案',`<p>每位角色可保存三組已套用的布置，包含背景、窗景與家具位置。</p><label class="field">方案名稱<input id="layout-name" maxlength="20" placeholder="例如：午茶小屋"></label>${button('保存目前布置','save-layout',plans.length>=3?'disabled':'')}${plans.map((p,i)=>`<div class="backup-row"><b>${esc(p.name)}</b><div>${button('套用','load-layout',`data-index="${i}"`)}${button('刪除','delete-layout',`data-index="${i}"`)}</div></div>`).join('')}`);}

async function pumpAuto(){clearTimeout(autoTimer);if(autoWorking||busy)return;const a=store.get().auto;if(!a?.active||a.owner!==autoOwner)return;if(Date.now()<a.nextAt){autoTimer=setTimeout(pumpAuto,Math.min(3000,a.nextAt-Date.now()));return;}autoWorking=true;try{let count=0;const quiet=document.hidden||Date.now()-a.nextAt>6000;await store.change(s=>{if(s.auto?.owner!==autoOwner||!s.auto.active)return;count=advanceAuto(s,Date.now(),quiet?100:1)});const next=store.get().auto;if(count&&next?.last){machine=next.machine;page='machine';lastGrid=next.last.grid;lastResult={win:next.last.win,note:next.last.note,awards:next.last.awards};if(!document.hidden){render();if(count===1&&!quiet){busy=true;beginPresentation();await spinReels($('.reel-window'),lastGrid,{...store.get().settings,fast:true});busy=false;render();}}}if(!next?.active&&!document.hidden)toast(next?.reason||'自動旋轉已停止')}catch(e){toast(e.message||'自動旋轉暫停');}finally{busy=false;autoWorking=false;const next=store.get().auto;if(next?.active&&next.owner===autoOwner)autoTimer=setTimeout(pumpAuto,Math.max(100,Math.min(3000,next.nextAt-Date.now())));}}
setInterval(()=>{const a=store.get().auto;if(a?.active&&a.owner===autoOwner&&!autoWorking&&!busy)void pumpAuto()},1000);
void pumpAuto();
